"""L10M closed-loop target policy with safety gating, lock hysteresis, and
heading-aware progress.  It confirms tracks before moving, preserves a lock
through brief occlusions, and chooses the least corrective action that keeps
the target centered in an available corridor.
"""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety-first finite-state control with stable target lock and
    bounded reacquisition memory; return (action, confidence, memory).
    """
    m = dict(memory or {})
    state = m.get("state", "IDLE")
    scan = m.get("scan_direction", "SCAN_LEFT")
    last_action = m.get("last_action", "STOP")
    lock_streak = int(m.get("lock_streak", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    tconf = float(observation["target_confidence"])
    iconf = float(observation["target_identity_confidence"])
    age = int(observation["track_age"])
    lost = int(observation["lost_steps"])
    safety = float(observation["safety_confidence"])
    risk = float(observation["closing_risk"])
    heading = abs(float(observation["heading_error"]))

    def finish(action, confidence, next_state):
        m["state"] = next_state
        m["last_action"] = action
        return action, confidence, m

    # Hard safety gate, including a latched stop until observations recover.
    if safety < 0.60 or risk >= 0.75:
        return finish("STOP", 0.99, "STOPPED")

    confirmed = visible and tconf >= 0.52 and iconf >= 0.58
    if not confirmed:
        # A single missed frame is handled by holding position; longer gaps
        # alternate scans while retaining the previously acquired target.
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost > 0:
            m["state"] = "REACQUIRE"
            if lost <= 1:
                return finish("STOP", 0.91, "REACQUIRE")
        action = scan
        m["scan_direction"] = "SCAN_RIGHT" if scan == "SCAN_LEFT" else "SCAN_LEFT"
        return finish(action, 0.72, "SEARCH")

    if age < 2:
        return finish("SLOW_DOWN", 0.80, "VERIFY")

    lock_streak = min(lock_streak + 1, 4)
    m["lock_streak"] = lock_streak

    if distance == "near":
        if heading <= 18.0 and iconf >= 0.78 and lock_streak >= 2:
            return finish("ARRIVED", 0.97, "ARRIVED")
        if bearing < -8.0 and observation["corridor_left"]:
            return finish("VEER_LEFT", 0.88, "APPROACH")
        if bearing > 8.0 and observation["corridor_right"]:
            return finish("VEER_RIGHT", 0.88, "APPROACH")
        if observation["corridor_center"] and heading <= 28.0:
            return finish("FORWARD", 0.84, "APPROACH")

    # Use a deadband to prevent left/right oscillation, while preferring
    # forward motion whenever the target is sufficiently centered.
    if abs(bearing) <= 10.0 and observation["corridor_center"]:
        return finish("FORWARD", 0.91, "APPROACH")

    if bearing < -10.0 and observation["corridor_left"]:
        return finish("VEER_LEFT", 0.90, "APPROACH")
    if bearing > 10.0 and observation["corridor_right"]:
        return finish("VEER_RIGHT", 0.90, "APPROACH")

    # If bearing is ambiguous or the preferred side is blocked, retain a
    # previously safe correction before falling back to the other corridor.
    if last_action == "VEER_LEFT" and observation["corridor_left"]:
        return finish("VEER_LEFT", 0.81, "APPROACH")
    if last_action == "VEER_RIGHT" and observation["corridor_right"]:
        return finish("VEER_RIGHT", 0.81, "APPROACH")
    if observation["corridor_center"]:
        return finish("FORWARD", 0.84, "APPROACH")
    if observation["corridor_left"]:
        return finish("VEER_LEFT", 0.78, "APPROACH")
    if observation["corridor_right"]:
        return finish("VEER_RIGHT", 0.78, "APPROACH")

    return finish("STOP", 0.98, "STOPPED")


# EVOLVE-BLOCK-END
